const materials=[
{id:'post-conexao',category:'Posts',title:'Uma loja mais conectada',description:'Post de apresentação do AutoZap com legenda personalizável.',format:'PNG · 1080 × 1080',kind:'post',headline:'Sua loja.\nMais conectada.',text:'Sua loja merece uma rotina mais conectada. Conheça a proposta do AutoZap para organizar atendimento, clientes e operação em um só lugar.\n\nQuer conhecer os recursos disponíveis para o seu negócio? Fale comigo: [CONTATO].\n\n[NOME] • Equipe AutoZap\n#AutoZap #GestãoDeLojas #LojasDeCelulares'},
{id:'logo',category:'Marca',title:'Logo AutoZap • símbolo',description:'Arquivo PNG original para compor seus materiais comerciais.',format:'PNG · 300 × 300',kind:'logo',file:'assets/logo.png'},
{id:'carta',category:'Cartas',title:'Carta de apresentação',description:'Uma apresentação profissional para o primeiro contato com a loja.',format:'TEXTO EDITÁVEL',kind:'letter',text:'Olá, equipe da [LOJA]!\n\nMeu nome é [NOME] e faço parte da equipe comercial AutoZap.\n\nGostaria de apresentar a proposta do AutoZap para lojas de celulares, acessórios e assistências técnicas: conectar o atendimento à organização da rotina comercial.\n\nPodemos conversar sobre como vocês trabalham hoje e apresentar os recursos disponíveis que fazem sentido para a loja.\n\nQual seria um bom horário para uma breve demonstração?\n\nAtenciosamente,\n[NOME]\nEquipe AutoZap\n[CONTATO]'},
{id:'whatsapp',category:'Mensagens',title:'Primeiro contato no WhatsApp',description:'Uma abordagem curta para abrir espaço para uma conversa.',format:'COPIAR E ADAPTAR',kind:'message',text:'Olá! Tudo bem? Sou [NOME], da equipe AutoZap. Falo com a pessoa responsável pela [LOJA]? Gostaria de entender como vocês organizam o atendimento e a operação da loja e apresentar nossa proposta. Podemos conversar?\n\nMeu contato: [CONTATO]'},
{id:'guia',category:'Guias',title:'Seu roteiro de demonstração',description:'Do diagnóstico ao próximo passo: organize uma conversa produtiva.',format:'GUIA · 5 ETAPAS',kind:'guide',text:'ROTEIRO DE DEMONSTRAÇÃO AUTOZAP\n\n1. ENTENDA A LOJA\nPergunte como a equipe acompanha conversas, orçamentos, estoque e serviços. Identifique a principal dificuldade.\n\n2. ESCOLHA UM CENÁRIO\nUse um exemplo com dados fictícios, próximo à rotina do cliente.\n\n3. MOSTRE O FLUXO\nApresente os recursos disponíveis na versão demonstrada. Confirme o funcionamento das integrações antes de incluí-las na apresentação.\n\n4. ESCUTE E CONFIRME\nPergunte o que ajudaria a equipe. Registre dúvidas que precisam de retorno.\n\n5. COMBINE O PRÓXIMO PASSO\nDefina a próxima conversa e confirme valores, condições, implantação e suporte com a equipe responsável antes de formalizar uma proposta.'},
{id:'post-atendimento',category:'Posts',title:'Cada conversa tem valor',description:'Criativo para despertar interesse na organização do atendimento.',format:'PNG · 1080 × 1080',kind:'post',headline:'Cada conversa.\nUma oportunidade.',text:'Como sua loja acompanha cada conversa com um cliente? Conheça a proposta do AutoZap para conectar atendimento e organização comercial.\n\nVamos conversar sobre sua rotina?\n[NOME] • [CONTATO]\n\n#AutoZap #Atendimento #Varejo'},
{id:'followup',category:'Mensagens',title:'Retomada após a demonstração',description:'Retome o contato com contexto e uma pergunta objetiva.',format:'COPIAR E ADAPTAR',kind:'message',text:'Olá, equipe da [LOJA]! Aqui é [NOME], da AutoZap. Obrigado pela conversa!\n\nQueria saber como vocês avaliaram o que apresentamos. Ficou alguma dúvida sobre o fluxo da loja ou os recursos demonstrados?\n\nPodemos combinar o próximo passo quando for conveniente.\n[CONTATO]'},
{id:'proposta',category:'Cartas',title:'Modelo de proposta comercial',description:'Estrutura para preencher escopo, condições e próximos passos.',format:'TEXTO EDITÁVEL',kind:'letter',text:'PROPOSTA COMERCIAL • AUTOZAP\n\nPara: [LOJA]\nResponsável comercial: [NOME]\nContato: [CONTATO]\nData: [PREENCHER]\n\nOBJETIVO\n[Descrever a necessidade identificada na conversa.]\n\nESCOPO\n[Listar somente os recursos, integrações e serviços confirmados para esta proposta.]\n\nCONDIÇÕES COMERCIAIS\nPlano e valor: [CONFIRMAR COM A EQUIPE]\nImplantação: [PREENCHER]\nPagamento: [PREENCHER]\nValidade da proposta: [PREENCHER]\nSuporte incluído: [PREENCHER]\n\nPRÓXIMOS PASSOS\n[Descrever o processo de contratação e implantação acordado.]\n\nDocumento preliminar. Preencher e validar as condições antes de apresentar ao cliente.'},
{id:'logo-completo',category:'Marca',title:'Logo AutoZap • assinatura',description:'Assinatura completa da marca em PNG para suas peças.',format:'PNG ORIGINAL',kind:'logo',file:'assets/logo-completo.png'},
{id:'objecoes',category:'Guias',title:'Perguntas que ajudam a vender',description:'Respostas orientadas à necessidade real de cada lojista.',format:'GUIA DE CONVERSA',kind:'guide',text:'PERGUNTAS PARA UMA BOA CONVERSA\n\n“Já tenho um sistema.”\nO que funciona bem hoje? Em que ponto a equipe ainda precisa usar planilhas ou controles separados?\n\n“Não tenho tempo para mudar.”\nQual processo mais toma tempo da equipe? Vamos avaliar juntos um primeiro passo possível.\n\n“Quanto custa?”\nVamos confirmar o escopo e consultar as condições comerciais vigentes para a sua loja.\n\n“Funciona com a minha integração?”\nVou confirmar a compatibilidade e o estado atual dessa integração com a equipe técnica antes de te responder.\n\n“Vai aumentar minhas vendas?”\nPodemos demonstrar como a proposta ajuda na organização da rotina. Resultados dependem do uso e da realidade de cada negócio.'},
{id:'links',category:'Links',title:'Endereços AutoZap',description:'Acesso ao domínio principal da marca para consultar informações.',format:'LINK EXTERNO',kind:'link',url:'https://autozap.log.br'},
{id:'post-rotina',category:'Posts',title:'Organização para sua rotina',description:'Um convite para conversar sobre os desafios da operação.',format:'PNG · 1080 × 1080',kind:'post',headline:'Menos pontas soltas.\nMais organização.',text:'Atendimento, clientes e operação fazem parte da mesma rotina. Que tal conhecer a proposta do AutoZap para conectar essas etapas na sua loja?\n\nConverse com [NOME]: [CONTATO]\n\n#AutoZap #AssistênciaTécnica #GestãoComercial'}
];
const $=s=>document.querySelector(s);let category='Todos',active=null,favorites=[];try{const f=JSON.parse(localStorage.getItem('autozap-equipe-favorites')||'[]');if(Array.isArray(f))favorites=f.filter(x=>typeof x==='string')}catch{}const categories=['Todos','Posts','Marca','Cartas','Mensagens','Guias','Links'];const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3000)}
function preview(m){if(m.kind==='post')return `<div class="mini-post"><small>AUTOZAP</small><strong>${esc(m.headline).replace('\n','<br>')}</strong><span>CONHEÇA UMA NOVA FORMA DE CONECTAR SUA ROTINA ↗</span></div>`;if(m.kind==='logo')return `<img src="${m.file}" alt="${m.title}">`;if(m.kind==='letter')return '<div class="sheet"><b>AutoZap</b><p>Vamos nos conectar.</p><div class="line"></div><div class="line"></div><div class="line short"></div><div class="line"></div><div class="line short"></div></div>';if(m.kind==='message')return '<div class="bubble">Olá! Tudo bem? 👋<br>Vamos conversar sobre<br>a rotina da sua loja?</div>';return `<div class="guide-preview"><span>${m.kind==='link'?'CONEXÕES AUTOZAP':'PLAYBOOK COMERCIAL'}</span>${m.kind==='link'?'O próximo passo<br>está aqui. ↗':'Uma boa conversa<br>começa aqui. ↗'}</div>`}
function render(){const q=normalize($('#search').value);const list=materials.filter(m=>(category==='Todos'||category==='Favoritos'&&favorites.includes(m.id)||m.category===category)&&normalize(m.title+' '+m.description+' '+m.category).includes(q));$('#cards').innerHTML=list.map(m=>`<article class="card"><div class="preview ${m.kind==='post'?'post':m.kind==='message'?'mint':m.kind==='letter'?'paper':''}">${preview(m)}<button class="bookmark ${favorites.includes(m.id)?'selected':''}" data-favorite="${m.id}" aria-label="Favoritar ${m.title}" aria-pressed="${favorites.includes(m.id)}">${favorites.includes(m.id)?'★':'☆'}</button></div><div class="card-info"><div class="meta"><span class="category">${m.category.toUpperCase()}</span><span>${m.kind==='post'?'MODELO':'AUTOZAP'}</span></div><h3>${m.title}</h3><p>${m.description}</p><button class="card-action" data-open="${m.id}"><span>${m.kind==='logo'?'Visualizar e baixar':m.kind==='link'?'Abrir endereço':m.kind==='guide'?'Ler o guia':'Usar este modelo'}</span><span>↗</span></button></div></article>`).join('');$('#count').textContent=`${list.length} ${list.length===1?'material disponível':'materiais disponíveis'}`;$('#empty').hidden=!!list.length;$('#sectionTitle').textContent=category==='Todos'?'Materiais para ir mais longe':category==='Favoritos'?'Seus materiais favoritos':category;document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===category);b.setAttribute('aria-pressed',String(b.dataset.category===category))})}
$('.filters').innerHTML=categories.map(c=>`<button data-category="${c}">${c==='Todos'?'Todos os materiais':c}</button>`).join('');
function select(c){category=c;render();$('#biblioteca').scrollIntoView({behavior:'smooth',block:'start'})}
function personalized(){return active.text.replaceAll('[NOME]',$('#rep').value||'[NOME]').replaceAll('[CONTATO]',$('#contact').value||'[CONTATO]').replaceAll('[LOJA]',$('#company').value||'[LOJA]')}
function openMaterial(id){active=materials.find(m=>m.id===id);if(active.kind==='link'){window.open(active.url,'_blank','noopener,noreferrer');return}$('#modalCategory').textContent=active.category+' / '+active.format;$('#modalTitle').textContent=active.title;$('#modalDescription').textContent=active.description;$('#personalize').hidden=!active.text;$('.fields').hidden=active.kind==='guide';$('#copy').hidden=!active.text;$('#downloadText').hidden=!active.text;$('#downloadArt').hidden=!['post','logo'].includes(active.kind);$('#downloadArt').textContent=active.kind==='logo'?'Baixar logo PNG':'Baixar arte PNG';$('#visualPreview').innerHTML=active.kind==='logo'?`<img src="${active.file}" alt="${active.title}">`:'';if(active.text)$('#bodyText').value=personalized();$('#editor').showModal()}
document.addEventListener('click',e=>{const c=e.target.closest('[data-category]');if(c)select(c.dataset.category);const q=e.target.closest('[data-quick]');if(q)select(q.dataset.quick);const o=e.target.closest('[data-open]');if(o)openMaterial(o.dataset.open);const f=e.target.closest('[data-favorite]');if(f){const id=f.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];try{localStorage.setItem('autozap-equipe-favorites',JSON.stringify(favorites))}catch{toast('Favorito marcado nesta sessão.')}render()}});
$('#search').addEventListener('input',render);$('#reset').onclick=()=>{$('#search').value='';select('Todos')};$('#explore').onclick=()=>select('Todos');$('#startGuide').onclick=()=>openMaterial('guia');$('#openLetter').onclick=()=>openMaterial('carta');$('#close').onclick=()=>$('#editor').close();$('#editor').addEventListener('click',e=>{if(e.target===$('#editor')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});document.querySelectorAll('.fields input').forEach(i=>i.addEventListener('input',()=>{$('#bodyText').value=personalized()}));
function download(url,name,revoke=false){const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();if(revoke)setTimeout(()=>URL.revokeObjectURL(url),10000)}
$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#bodyText').value);toast('Texto copiado!')}catch{$('#bodyText').focus();$('#bodyText').select();toast('Selecione Copiar no seu dispositivo ou pressione Ctrl+C.')}};$('#downloadText').onclick=()=>download(URL.createObjectURL(new Blob(['\ufeff'+$('#bodyText').value],{type:'text/plain;charset=utf-8'})),`autozap-${active.id}.txt`,true);
async function generatePost(m){await document.fonts.ready;const canvas=document.createElement('canvas');canvas.width=canvas.height=1080;const ctx=canvas.getContext('2d');const g=ctx.createLinearGradient(0,0,1080,1080);g.addColorStop(0,'#061b39');g.addColorStop(1,'#1269dc');ctx.fillStyle=g;ctx.fillRect(0,0,1080,1080);ctx.strokeStyle='#ffffff14';ctx.lineWidth=2;[280,390,500].forEach(r=>{ctx.beginPath();ctx.arc(1000,830,r,0,Math.PI*2);ctx.stroke()});ctx.fillStyle='#9dccff';ctx.font='600 22px Manrope, sans-serif';ctx.fillText('AUTOZAP  /  CONECTE SUA ROTINA',80,110);ctx.fillStyle='white';ctx.font='800 76px Manrope, sans-serif';m.headline.split('\n').forEach((line,i)=>ctx.fillText(line,80,350+i*100,920));ctx.fillStyle='#c4ddfc';ctx.font='400 30px Manrope, sans-serif';ctx.fillText('Atendimento, clientes e operação.',80,610);ctx.fillText('Conheça a proposta AutoZap para sua loja.',80,657);const logo=new Image();logo.src='assets/logo.png';await logo.decode();ctx.drawImage(logo,790,720,210,210);ctx.fillStyle='white';ctx.font='600 26px Manrope, sans-serif';ctx.fillText($('#rep').value||'Equipe AutoZap',80,900,680);ctx.fillStyle='#b6d5ff';ctx.font='400 24px Manrope, sans-serif';ctx.fillText($('#contact').value||'Conheça o AutoZap • autozap.log.br',80,950,680);return canvas}
$('#downloadArt').onclick=async()=>{if(active.kind==='logo'){download(active.file,'autozap-'+active.id+'.png');return}const button=$('#downloadArt');button.disabled=true;try{const canvas=await generatePost(active);canvas.toBlob(blob=>{if(blob){download(URL.createObjectURL(blob),'autozap-'+active.id+'.png',true);toast('Arte pronta para baixar.')}else toast('Não foi possível gerar a arte. Tente novamente.')},'image/png')}catch{toast('Não foi possível gerar a arte. Tente novamente.')}finally{button.disabled=false}};render();
